css:
.hcm-page {
max-width: 560px;
margin: 0 auto;
padding: 16px 12px 48px;
color: #22262b;
font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
line-height: 1.6;
}
.hcm-badge {
margin: 0 0 10px;
font-size: 11px;
letter-spacing: 0.08em;
text-transform: uppercase;
color: #5b6b80;
}
/* ---- 도화지 ------------------------------------------- */
/* 실제 크기를 눈으로 확인할 수 있게 얇은 테두리를 두른다 */
.hcm-canvas {
width: 100%;
max-width: 520px;
margin: 0 auto;
background: #ffffff;
outline: 1px solid #c6cfda;
}
/* ---- 요소 공통 ---------------------------------------- */
/* 경계가 보이도록 아주 얇은 선만 준다 — 배치를 확인하는 선이다 */
.hcm-canvas [data-imory-canvas-element] {
outline: 1px dashed rgba(91, 107, 128, 0.55);
}
/* 잠긴 배경은 선을 빼고 아주 옅은 바탕만 준다 */
.hcm-canvas [data-imory-canvas-locked] {
outline: none;
background: #f7f9fb;
}
/* ---- photo · sticker · logo --------------------------- */
/* 빈 슬롯에서도 틀이 보이게 — 그림이 들어오면 그 위를 덮는다 */
.hcm-canvas [data-imory-canvas-type="photo"],
.hcm-canvas [data-imory-canvas-type="sticker"],
.hcm-canvas [data-imory-canvas-type="logo"] {
background: #eef2f7;
}
/* object-fit 이 듣는지 보려면 틀과 그림의 비율이 달라야 한다 */
.hcm-canvas [data-imory-canvas-image] {
border-radius: 2px;
}
.hcm-canvas [data-imory-canvas-logo-text] {
font-size: 18px;
font-weight: 600;
letter-spacing: 0.04em;
color: #1d3557;
}
/* ---- 글자 --------------------------------------------- */
.hcm-canvas [data-imory-canvas-role="title"] {
font-size: 22px;
font-weight: 700;
letter-spacing: -0.01em;
color: #1a1d21;
}
.hcm-canvas [data-imory-canvas-role="body"] {
font-size: 13px;
color: #2f353c;
}
.hcm-canvas [data-imory-canvas-role="caption"] {
font-size: 12px;
color: #5b6b80;
}
/* ---- 도형 --------------------------------------------- */
.hcm-canvas [data-imory-canvas-shape="rect"] {
background: #eaeff5;
}
.hcm-canvas [data-imory-canvas-shape="ellipse"] {
background: #1d3557;
opacity: 0.18;
}
.hcm-canvas [data-imory-canvas-shape="line"] {
background: #1d3557;
}
/* 잠긴 배경은 위의 rect 규칙보다 뒤에 와서 옅은 바탕을 지킨다 */
.hcm-canvas [data-imory-canvas-locked][data-imory-canvas-shape="rect"] {
background: #f7f9fb;
}
/* ---- 카테고리 ----------------------------------------- */
.hcm-canvas [data-imory-canvas-nav-item] {
display: inline-block;
margin: 0 10px 4px 0;
font-size: 12px;
letter-spacing: 0.06em;
text-transform: uppercase;
color: #1d3557;
text-decoration: none;
border-bottom: 1px solid #1d3557;
}
/* ---- 도화지 밖 ---------------------------------------- */
.hcm-owner {
margin: 14px 0 0;
display: flex;
gap: 10px;
}
.hcm-owner-link {
font-size: 11px;
letter-spacing: 0.08em;
color: #1d3557;
text-decoration: none;
border: 1px solid #c6cfda;
padding: 4px 10px;
}
.hcm-foot {
margin: 20px 0 0;
font-size: 11px;
color: #7c8798;
}
/* ---- 다른 화면 ---------------------------------------- */
.hcm-crumb {
margin: 0 0 8px;
font-size: 11px;
letter-spacing: 0.08em;
text-transform: uppercase;
}
.hcm-crumb a {
color: #5b6b80;
text-decoration: none;
}
.hcm-head {
margin: 0 0 6px;
font-size: 20px;
font-weight: 700;
}
.hcm-date {
margin: 0 0 14px;
font-size: 11px;
color: #7c8798;
}
.hcm-list {
margin: 14px 0 0;
padding: 0;
list-style: none;
}
.hcm-list-item {
border-top: 1px solid #e6eaf0;
}
.hcm-list-link {
display: block;
padding: 10px 0;
font-size: 14px;
color: #22262b;
text-decoration: none;
}
.hcm-series {
margin: 24px 0 0;
border-top: 1px solid #e6eaf0;
padding-top: 14px;
}
.hcm-series-title {
margin: 0 0 8px;
font-size: 16px;
font-weight: 600;
}
.hcm-body {
font-size: 14px;
}
